/**
 * The newest date listed in the producer's VersioningConfig at gen time; identical in every app of
 * the workspace.
 */
export const apiVersion = "2027-03-01" as const;

/** `orders.OrderStatus`: labels are `orders::enums.order_status.<code>`, tones colour the badge. */
export const OrderStatus = Enum.of({
  PendingPayment: ["pending_payment", { tone: Tone.Warning }],
  Paid: ["paid", { tone: Tone.Success }],
  Cancelled: ["cancelled", { tone: Tone.Default }],
  Expired: ["expired", { tone: Tone.Default }],
});

/** One of the `orders.OrderStatus` codes. */
export type OrderStatus = Enum.Value<typeof OrderStatus>;

/** `orders.CancelReason`: labels are `orders::enums.cancel_reason.<code>`. */
export const CancelReason = Enum.of({
  Customer: "customer",
  Staff: "staff",
  Expired: "expired",
  PaymentFailed: "payment_failed",
});

/** One of the `orders.CancelReason` codes. */
export type CancelReason = Enum.Value<typeof CancelReason>;

/** `catalogue.ProductStatus`: labels are `catalogue::enums.product_status.<code>`. */
export const ProductStatus = Enum.of({
  Draft: "draft",
  Active: "active",
  Archived: "archived",
});

/** One of the `catalogue.ProductStatus` codes. */
export type ProductStatus = Enum.Value<typeof ProductStatus>;

/** `inventory.StockAdjustReason`: labels are `inventory::enums.stock_adjust_reason.<code>`. */
export const StockAdjustReason = Enum.of({
  Count: "count",
  Delivery: "delivery",
  Damage: "damage",
});

/** One of the `inventory.StockAdjustReason` codes. */
export type StockAdjustReason = Enum.Value<typeof StockAdjustReason>;

/** `messages.NotificationKind`: labels are `messages::enums.notification_kind.<code>`. */
export const NotificationKind = Enum.of({ OrderPaid: "order_paid" });

/** One of the `messages.NotificationKind` codes. */
export type NotificationKind = Enum.Value<typeof NotificationKind>;

/** `loyalty_kit.LoyaltyTier`: labels are `loyalty_kit::enums.loyalty_tier.<code>`. */
export const LoyaltyTier = Enum.of({
  Bronze: "bronze",
  Silver: "silver",
  Gold: "gold",
});

/** One of the `loyalty_kit.LoyaltyTier` codes. */
export type LoyaltyTier = Enum.Value<typeof LoyaltyTier>;

/** `access_log.DataClassification`: labels are `access_log::enums.data_classification.<code>`. */
export const DataClassification = Enum.of({
  Personal: "personal",
  Financial: "financial",
  Health: "health",
  Pseudonymous: "pseudonymous",
});

/** One of the `access_log.DataClassification` codes. */
export type DataClassification = Enum.Value<typeof DataClassification>;

/** `orders.RequestedLine$`: one line of an order request. */
const RequestedLine$ = z.object({
  variantId: publicId("var"),
  quantity: z.number().int().min(1),
});

/** `orders.CreateOrderInput$`: the lines (1 to 100) and the extension inputs. */
const CreateOrderInput$ = z.object({
  lines: z.array(RequestedLine$).min(1).max(100),
  extensions: z
    .object({
      loyalty: z.object({ redeemPoints: z.number().int().min(1).max(1_000_000) }).exactOptional(),
    })
    .default({}),
});

/** `catalogue.CreateProductInput$`: the model's writable fields, from `operations.create: true`. */
const CreateProductInput$ = z.object({
  title: z.record(z.string(), z.string().max(200)),
  slug: z
    .string()
    .max(200)
    .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  description: z.record(z.string(), z.string().max(200)).nullable().exactOptional(),
  collections: z.array(z.object({ title: z.string(), slug: z.string() })).exactOptional(),
});

/** `catalogue.UpdateProductInput$`: the partial update, addressed by `productId`. */
const UpdateProductInput$ = CreateProductInput$.partial().extend({ productId: publicId("prd") });

/** `inventory.ListLowStockInput$`. */
const ListLowStockInput$ = z.object({ limit: z.number().int().min(1).max(100).default(20) });

/** `inventory.ListLowStockOutput$`: rows at or below the tenant's threshold, lowest first. */
const ListLowStockOutput$ = z.object({
  items: z.array(
    z.object({
      variantId: publicId("var"),
      locationId: z.string(),
      available: z.number().int(),
    }),
  ),
});

/** `orders.OrderTotals$`. */
export const OrderTotals$ = z.object({
  currency: currencyCode(),
  subtotalMinor: z.number().int().min(0),
  adjustments: z.array(
    z.object({ code: z.string(), label: z.string(), amountMinor: z.number().int() }),
  ),
  totalMinor: z.number().int().min(0),
});

/** `orders.OrderView$`: the item of `orders.order.get@1` and `orders.order.list@1`. */
export const OrderView$ = z.object({
  id: publicId("ord"),
  status: z.enum(Enum.values(OrderStatus)),
  totals: OrderTotals$,
  lines: z.array(
    z.object({
      variantId: publicId("var"),
      quantity: z.number().int(),
      unitPriceMinor: z.number().int(),
    }),
  ),
  createdAt: z.iso.datetime({ offset: true }),
});

/** One order as the console reads it. */
export type OrderView = z.output<typeof OrderView$>;

/** `orders.OrdersTodayOutput$`: the output of `orders.order.stats_today@1`. */
export const OrdersTodayOutput$ = z.object({
  count: z.number().int(),
  revenueMinor: z.number().int(),
  currency: currencyCode(),
  hourly: z.array(z.number().int()).length(24),
});

/** `catalogue.VariantHit$`: one row of `catalogue.variant.search@1`. */
export const VariantHit$ = z.object({
  variantId: publicId("var"),
  productId: publicId("prd"),
  sku: z.string(),
  title: z.string(),
  trackInventory: z.boolean(),
});

/** One variant search hit, as the quick-order picker lists it. */
export type VariantHit = z.output<typeof VariantHit$>;

/** `catalogue.ProductView$`: the console's view of a product. */
export const ProductView$ = z.object({
  id: publicId("prd"),
  title: z.string(),
  slug: z.string(),
  status: z.enum(Enum.values(ProductStatus)),
  variants: z.array(z.object({ id: publicId("var"), sku: z.string() })),
});

/**
 * `messages.NotificationView$`: one entry of the in-app inbox; the client renders the kind's label
 * with `data`.
 */
export const NotificationView$ = z.object({
  id: publicId("ntf"),
  kind: z.enum(Enum.values(NotificationKind)),
  data: z.record(z.string(), z.union([z.string(), z.number()])),
  createdAt: z.iso.datetime({ offset: true }),
  readAt: z.iso.datetime({ offset: true }).nullable(),
});

/** One inbox entry as the console reads it. */
export type NotificationView = z.output<typeof NotificationView$>;

/** `loyalty_kit.LoyaltyAccountView$`: one account as the loyalty resource lists and shows it. */
export const LoyaltyAccountView$ = z.object({
  accountId: publicId("lac"),
  memberId: z.string(),
  tier: z.enum(Enum.values(LoyaltyTier)),
  isFrozen: z.boolean(),
  createdAt: z.iso.datetime({ offset: true }),
});

/** `loyalty_kit.BalanceView$`: the output of `loyalty_kit.points.balance@1`. */
export const BalanceView$ = z.object({
  memberId: z.string(),
  tier: z.enum(Enum.values(LoyaltyTier)),
  balance: z.number().int().min(0),
  nextExpiryAt: z.iso.datetime({ offset: true }).nullable(),
});

/** `access_log.AccessLogEntry$`: one access record, exactly as stored. */
export const AccessLogEntry$ = z.object({
  id: publicId("acl"),
  callId: z.string().max(64),
  target: z.string().max(200),
  classification: z.enum(Enum.values(DataClassification)),
  actor: z.json(),
  subjects: z.array(z.string()),
  at: z.iso.datetime({ offset: true }),
});

/** A cursor page of `T`, the shape every list query returns. */
const page = <T extends z.ZodType>(item: T) =>
  z.object({
    items: z.array(item),
    nextCursor: z.string().exactOptional(),
    hasMore: z.boolean(),
  });

/** A cursor-page request with the house bounds. */
const pageInput = z.object({
  cursor: z.string().exactOptional(),
  limit: z.number().int().min(1).max(100).default(20),
});

