/** The notifications service: the in-app inbox and the per-user notification preferences. */
export const Notifications = {
  actions: {
    MarkNotificationRead: actionRef("messages.notification.mark_read@1", {
      input: z.object({ notificationId: publicId("ntf") }),
      output: NotificationView$,
      http: { method: HttpMethod.Put, path: "/notifications/:notificationId/read" },
      risk: Risk.L0,
    }),
  },
  queries: {
    /** `unread` counts the actor's whole inbox, not the page. */
    ListNotifications: queryRef("messages.notification.list@1", {
      input: pageInput.extend({ unreadOnly: z.boolean().default(false) }),
      output: page(NotificationView$).extend({ unread: z.number().int().nonnegative() }),
      http: { method: HttpMethod.Get, path: "/notifications" },
    }),
  },
  permissions: {
    Notification: {
      read: permissionRef("messages.notification.read"),
      update: permissionRef("messages.notification.update"),
    },
  },
  events: {
    /**
     * Broadcast as a data-free refresh to the tenant's sessions that hold
     * `messages.notification.read`; the inbox refetches its own entries.
     */
    NotificationCreated: eventRef("messages.notification.created.v1", {
      payload: z.object({
        notificationId: publicId("ntf"),
        principalId: publicId("usr"),
        kind: z.enum(Enum.values(NotificationKind)),
      }),
      channel: "tenant.{tenantId}.messages",
    }),
  },
  refusals: {
    notification_not_found: refusalRef("messages.notification_not_found", {
      message: I18n.messages.errors.notification_not_found.message,
    }),
  },
  enums: { NotificationKind },
} as const;

/** The platform service (acme-platform, pinned): settings values. */
export const Platform = {
  actions: {
    SetSettingValues: actionRef("settings.value.set", {
      input: z.object({
        scope: z.enum(Enum.values(SettingScope)),
        values: z.record(z.string(), z.union([z.string(), z.number(), z.boolean()])),
      }),
      output: z.object({ revision: z.string() }),
      http: { method: HttpMethod.Put, path: "/settings/values" },
      risk: Risk.L2,
    }),
  },
  permissions: { Settings: { manage: permissionRef("settings.value.manage") } },
  refusals: {
    settings_locked: refusalRef("settings.settings_locked", {
      message: I18n.settings.refusals.settings_locked,
    }),
  },
} as const;

/**
 * The experience service (acme-platform, pinned): the one document query every app reaches
 * through its route adapter.
 */
export const Experience = {
  queries: {
    GetDocument: queryRef("experience.document.get", {
      input: z.union([z.object({ key: z.string() }), z.object({ path: z.string() })]),
      output: z
        .object({ key: z.string(), version: z.number().int(), root: z.unknown() })
        .nullable(),
      http: { method: HttpMethod.Get, path: "/experience/documents" },
    }),
  },
  permissions: { Document: { publish: permissionRef("experience.document.publish") } },
  refusals: {
    not_found: refusalRef("experience.not_found", { message: I18n.experience.refusals.not_found }),
  },
} as const;

/** The identity service (acme-platform, pinned): the BFF session. */
export const Identity = {
  queries: {
    CurrentSession: queryRef("identity.session.current", {
      input: z.object({}),
      output: z
        .object({
          user: z.object({
            userId: z.string(),
            displayName: z.string(),
            avatarUrl: z.string().exactOptional(),
            permissions: z.array(z.string()),
            tenants: z.array(
              z.object({ tenantId: z.string(), name: z.string(), role: z.string() }),
            ),
          }),
        })
        .nullable(),
      http: { method: HttpMethod.Get, path: "/api/auth/session" },
    }),
  },
} as const;
